//! Fork copies are generated by the SDK in private staging and published only
//! after the restricted writer exits. The source child is never given to it.
use std::io::{BufRead, Read, Write};
use std::path::{Path, PathBuf};
use std::time::Duration;
use serde_json::{json, Value};
use crate::pi_ipc::IpcHostState;

fn error(code: &str, message: impl ToString) -> (String, String) { (code.into(), message.to_string()) }

struct Prepared {
    writer: crate::session_writer_lifecycle::WriterGuard,
    operation: String,
    target: String,
    staging: PathBuf,
    source: std::fs::File,
    source_path: PathBuf,
    source_digest: Vec<u8>,
    cancelled: bool,
}

#[cfg(unix)]
fn private_dir(path: &Path) -> Result<(), (String, String)> {
    use std::os::unix::fs::DirBuilderExt;
    std::fs::DirBuilder::new().recursive(true).mode(0o700).create(path).map_err(|e| error("io", e))?;
    let metadata = std::fs::symlink_metadata(path).map_err(|e| error("io", e))?;
    if !metadata.file_type().is_dir() || metadata.file_type().is_symlink() { return Err(error("access_denied", "Unsafe fork staging directory")); }
    Ok(())
}

#[cfg(unix)]
fn create_private(path: &Path, bytes: &[u8]) -> Result<(), (String, String)> {
    use std::os::unix::fs::OpenOptionsExt;
    let mut file = std::fs::OpenOptions::new().write(true).create_new(true).mode(0o600).open(path).map_err(|e| error("io", e))?;
    file.write_all(bytes).and_then(|_| file.sync_all()).map_err(|e| error("io", e))
}

#[cfg(unix)]
fn sync_dir(path: &Path) -> Result<(), (String, String)> {
    std::fs::File::open(path).and_then(|file| file.sync_all()).map_err(|e| error("io", e))
}

#[cfg(unix)]
fn source_identity_matches(handle: &std::fs::File, path: &Path) -> bool {
    use std::os::unix::fs::MetadataExt;
    match (handle.metadata(), std::fs::symlink_metadata(path)) {
        (Ok(opened), Ok(current)) => current.file_type().is_file() && opened.dev() == current.dev() && opened.ino() == current.ino(),
        _ => false,
    }
}

#[cfg(unix)]
fn source_digest(handle: &std::fs::File) -> Result<Vec<u8>, (String, String)> {
    use sha2::{Digest, Sha256};
    use std::io::{Seek, SeekFrom};
    let mut file = handle.try_clone().map_err(|e| error("io", e))?;
    file.seek(SeekFrom::Start(0)).map_err(|e| error("io", e))?;
    let mut digest = Sha256::new();
    std::io::copy(&mut file, &mut digest).map_err(|e| error("io", e))?;
    Ok(digest.finalize().to_vec())
}

#[cfg(unix)]
fn write_live_snapshot(path: &Path, header: &Value, entries: &[Value]) -> Result<(), (String, String)> {
    let mut body = serde_json::to_vec(header).map_err(|e| error("outcome_unknown", e))?;
    body.push(b'\n');
    for row in entries { body.extend(serde_json::to_vec(row).map_err(|e| error("outcome_unknown", e))?); body.push(b'\n'); }
    create_private(path, &body).map_err(|e| error("outcome_unknown", e.1))
}

#[cfg(unix)]
fn validate_staged_entries(bytes: &[u8]) -> Result<usize, (String, String)> {
    if !bytes.ends_with(b"\n") { return Err(error("outcome_unknown", "Incomplete staged fork")); }
    let mut lines = bytes.split(|byte| *byte == b'\n');
    let header = lines.next().ok_or_else(|| error("outcome_unknown", "Missing staged fork header"))?;
    let mut ids = std::collections::HashSet::new();
    for line in lines {
        if line.is_empty() { continue; }
        let entry: Value = serde_json::from_slice(line).map_err(|_| error("outcome_unknown", "Invalid staged fork entry"))?;
        let id = entry.get("id").and_then(Value::as_str).filter(|id| !id.is_empty()).ok_or_else(|| error("outcome_unknown", "Invalid staged fork entry identity"))?;
        if entry.get("type").and_then(Value::as_str).is_none() || !ids.insert(id.to_owned()) {
            return Err(error("outcome_unknown", "Duplicate or invalid staged fork entry"));
        }
        match entry.get("parentId") {
            Some(Value::Null) => {},
            Some(Value::String(parent)) if ids.contains(parent) && parent != id => {},
            _ => return Err(error("outcome_unknown", "Invalid staged fork parent")),
        }
    }
    Ok(header.len())
}

#[cfg(unix)]
fn publish_noreplace(prepared: &Path, destination: &Path) -> Result<(), (String, String)> {
    std::fs::hard_link(prepared, destination).map_err(|e| error("outcome_unknown", format!("Fork publish failed; do not retry: {e}")))?;
    sync_dir(destination.parent().ok_or_else(|| error("outcome_unknown", "Missing target directory"))?).map_err(|e| error("outcome_unknown", e.1))
}

#[cfg(unix)]
pub(crate) fn copy(state: &IpcHostState, id: &str, kind: &str, args: &Value) -> Result<Value, (String, String)> {
    crate::chat_sessions::writer_config(state)?;
    let agent = state.agent_dir();
    let result = state.registry.with_idle_session_copy(id, Duration::from_secs(5), |live| {
        let session = live.ok_or_else(|| error("busy", "Session is no longer active; refresh before forking"))?;
        if !session.session_file.is_file() { return Ok((None, false)); }
        session.bridge_request("tree.assertIdle", None, Some(Duration::from_secs(30))).map_err(|e| error("busy", e))?;
        let snapshot = session.command("get_entries", json!({}), Some(Duration::from_secs(30))).map_err(|e| error("op_failed", e))?;
        let entries = snapshot.get("entries").and_then(Value::as_array).ok_or_else(|| error("op_failed", "Invalid live session snapshot"))?;
        let entry = if kind == "clone" {
            args.get("leafId").and_then(Value::as_str).or_else(|| snapshot.get("leafId").and_then(Value::as_str))
        } else { args.get("entryId").and_then(Value::as_str) };
        let Some(entry) = entry else { return Ok((None, false)); };
        if !entries.iter().any(|row| row.get("id").and_then(Value::as_str) == Some(entry)) { return Err(error("invalid_args", "Invalid entry ID for forking")); }
        let root = agent.join("sessions").canonicalize().map_err(|e| error("io", e))?;
        let file = session.session_file.canonicalize().map_err(|e| error("io", e))?;
        if !file.starts_with(&root) { return Err(error("access_denied", "Session is outside session storage")); }
        let source_handle = std::fs::File::open(&file).map_err(|e| error("io", e))?;
        if !source_identity_matches(&source_handle, &file) { return Err(error("access_denied", "Session source identity changed")); }
        let mut header_line = String::new();
        std::io::BufReader::new(&source_handle).take(65537).read_line(&mut header_line).map_err(|e| error("io", e))?;
        if header_line.len() > 65536 { return Err(error("invalid_args", "Session header is too large")); }
        let header: Value = serde_json::from_str(&header_line).map_err(|_| error("invalid_args", "Invalid session header"))?;
        if header.get("type").and_then(Value::as_str) != Some("session")
            || header.get("id").and_then(Value::as_str) != Some(session.session_file_id.as_str())
            || header.get("cwd").and_then(Value::as_str) != session.cwd.to_str() {
            return Err(error("invalid_args", "Session header does not match the live session"));
        }
        let original_digest = source_digest(&source_handle)?;
        let operation = crate::chat_sessions::random_id()?;
        let mut writer = state.session_writers.admit(&operation).map_err(|e| error("busy", e))?;
        let target = crate::chat_sessions::random_id()?;
        let staging_root = agent.join("pi-web/fork-staging");
        let staging = staging_root.join(&operation);
        let destination_dir = file.parent().ok_or_else(|| error("io", "Session directory missing"))?;
        let destination = destination_dir.join(format!("fork-{target}.jsonl"));
        if session_host::history::find_session_by_id(&agent, &target).is_some() || destination.exists() { return Err(error("busy", "Generated session identity already exists")); }
        crate::session_writer_fence::begin_fork(&agent, id, &operation, "fork-source", &file, destination_dir, &target, &staging).map_err(|e| error("outcome_unknown", e))?;
        crate::session_writer_fence::begin_fork(&agent, &target, &operation, "fork-target", &file, destination_dir, &target, &staging).map_err(|e| error("outcome_unknown", e))?;
        if !source_identity_matches(&source_handle, &file) { return Err(error("outcome_unknown", "Session source identity changed")); }
        let base = agent.join("pi-web");
        private_dir(&base).map_err(|e| error("outcome_unknown", e.1))?;
        private_dir(&staging_root).map_err(|e| error("outcome_unknown", e.1))?;
        {
            use std::os::unix::fs::MetadataExt;
            let meta = std::fs::symlink_metadata(&staging_root).map_err(|e| error("outcome_unknown", e))?;
            if meta.mode() & 0o077 != 0 || meta.uid() != unsafe { libc::geteuid() } {
                return Err(error("outcome_unknown", "Fork staging directory is not private"));
            }
        }
        {
            use std::os::unix::fs::DirBuilderExt;
            std::fs::DirBuilder::new().mode(0o700).create(&staging).map_err(|e| error("outcome_unknown", e))?;
        }
        sync_dir(&staging_root).map_err(|e| error("outcome_unknown", e.1))?;
        let snapshot_file = staging.join("source.jsonl");
        write_live_snapshot(&snapshot_file, &header, entries)?;
        sync_dir(&staging).map_err(|e| error("outcome_unknown", e.1))?;
        let answer = crate::chat_sessions::run_writer(state, &mut writer, "session.forkStaged", json!({"snapshot":snapshot_file,"staging":staging,"entryId":entry,"mode":kind}))?;
        let cancelled = answer.get("cancelled").and_then(Value::as_bool).ok_or_else(|| error("outcome_unknown", "Invalid fork result; do not retry"))?;
        if !cancelled {
            let output = answer.get("path").and_then(Value::as_str).ok_or_else(|| error("outcome_unknown", "Missing fork output; do not retry"))?;
            let output = Path::new(output).canonicalize().map_err(|e| error("outcome_unknown", e))?;
            let staging_canonical = staging.canonicalize().map_err(|e| error("outcome_unknown", e))?;
            let snapshot_canonical = snapshot_file.canonicalize().map_err(|e| error("outcome_unknown", e))?;
            if output.parent() != Some(staging_canonical.as_path()) || output == snapshot_canonical { return Err(error("outcome_unknown", "Invalid staged fork; do not retry")); }
            let bytes = std::fs::read(&output).map_err(|e| error("outcome_unknown", e))?;
            let split = validate_staged_entries(&bytes)?;
            let mut new_header: Value = serde_json::from_slice(&bytes[..split]).map_err(|e| error("outcome_unknown", e))?;
            if new_header.get("type").and_then(Value::as_str) != Some("session")
                || new_header.get("id").and_then(Value::as_str).is_none_or(str::is_empty)
                || new_header.get("cwd").and_then(Value::as_str) != session.cwd.to_str()
                || new_header.get("parentSession").and_then(Value::as_str) != snapshot_canonical.to_str() {
                return Err(error("outcome_unknown", "Staged fork identity mismatch"));
            }
            let obj = new_header.as_object_mut().ok_or_else(|| error("outcome_unknown", "Invalid staged fork header"))?;
            obj.insert("id".into(), json!(target));
            obj.insert("parentSession".into(), json!(file));
            obj.insert("cwd".into(), json!(session.cwd));
            let mut prepared = serde_json::to_vec(&new_header).map_err(|e| error("outcome_unknown", e))?;
            prepared.push(b'\n');
            prepared.extend_from_slice(&bytes[split + 1..]);
            let prepared_file = staging.join("prepared.jsonl");
            create_private(&prepared_file, &prepared).map_err(|e| error("outcome_unknown", e.1))?;
            sync_dir(&staging).map_err(|e| error("outcome_unknown", e.1))?;
            if !source_identity_matches(&source_handle, &file) { return Err(error("outcome_unknown", "Session source identity changed")); }
            publish_noreplace(&prepared_file, &destination)?;
            let target_header = session_host::history::read_header_summary(&destination).map_err(|e| error("outcome_unknown", e))?;
            if target_header.id != target || target_header.parent_session.as_deref() != file.to_str() || target_header.cwd != session.cwd.to_string_lossy() {
                return Err(error("outcome_unknown", "Published fork identity mismatch; do not retry"));
            }
        }
        Ok((Some(Prepared { writer, operation, target, staging, source: source_handle, source_path: file, source_digest: original_digest, cancelled }), !cancelled && kind != "fork_branch"))
    }, |prepared| {
        let Some(prepared) = prepared else { return Ok(json!({"cancelled":true})); };
        if !source_identity_matches(&prepared.source, &prepared.source_path)
            || source_digest(&prepared.source).map_err(|e| error("outcome_unknown", e.1))? != prepared.source_digest {
            return Err(error("outcome_unknown", "Source changed during fork; do not retry"));
        }
        let outcome = if prepared.cancelled { crate::session_writer_fence::FenceOutcome::NotApplied } else { crate::session_writer_fence::FenceOutcome::Applied };
        let target_cleanup = crate::session_writer_fence::finish_known(&agent, &prepared.target, &prepared.operation, outcome).err();
        let source_cleanup = crate::session_writer_fence::finish_known(&agent, id, &prepared.operation, outcome).err();
        prepared.writer.complete();
        let staging_cleanup = std::fs::remove_dir_all(&prepared.staging).err().map(|e| e.to_string());
        let cleanup_warning = target_cleanup.or(source_cleanup).or(staging_cleanup).map(|e| format!("Fork outcome is known, but cleanup is uncertain; do not repeat the operation: {e}"));
        Ok(if prepared.cancelled { json!({"cancelled":true,"cleanupWarning":cleanup_warning}) } else { json!({"cancelled":false,"newSessionId":prepared.target,"cleanupWarning":cleanup_warning}) })
    });
    match result {
        Ok(value) => Ok(value),
        Err(session_host::SessionWriterError::Busy(message)) if message.starts_with("copy completed") => Err(error("outcome_unknown", message)),
        Err(session_host::SessionWriterError::Busy(message)) => Err(error("busy", message)),
        Err(session_host::SessionWriterError::Operation((code, message))) if code == "outcome_unknown" =>
            Err(error("outcome_unknown", format!("Fork outcome unknown; do not retry: {message}"))),
        Err(session_host::SessionWriterError::Operation(error)) => Err(error),
    }
}

#[cfg(not(unix))]
pub(crate) fn copy(_state: &IpcHostState, _id: &str, _kind: &str, _args: &Value) -> Result<Value, (String, String)> {
    Err(error("not_supported", "Safe session fork is unavailable on this platform"))
}

#[cfg(all(test, unix))]
mod tests {
    use super::*;
    #[test]
    fn snapshot_keeps_live_only_entries_without_touching_source() {
        let temp = tempfile::tempdir().unwrap();
        let source = temp.path().join("source");
        let snapshot = temp.path().join("snapshot");
        std::fs::write(&source, b"original").unwrap();
        let header = json!({"type":"session","id":"source","cwd":"/fixture"});
        let entries = [json!({"type":"message","id":"memory-only","parentId":null,"message":{"role":"user","content":"draft"}})];
        write_live_snapshot(&snapshot, &header, &entries).unwrap();
        assert_eq!(std::fs::read(&source).unwrap(), b"original");
        assert!(std::fs::read_to_string(snapshot).unwrap().contains("memory-only"));
    }

    #[test]
    fn publish_never_replaces_existing_session() {
        let temp = tempfile::tempdir().unwrap();
        let prepared = temp.path().join("prepared");
        let target = temp.path().join("target");
        std::fs::write(&prepared, b"new").unwrap();
        std::fs::write(&target, b"original").unwrap();
        let agent = temp.path().join("agent");
        std::fs::create_dir_all(&agent).unwrap();
        let source = temp.path().join("source");
        std::fs::write(&source, b"source").unwrap();
        crate::session_writer_fence::begin_fork(&agent, "source", "op", "fork-source", &source, temp.path(), "target", temp.path()).unwrap();
        crate::session_writer_fence::begin_fork(&agent, "target", "op", "fork-target", &source, temp.path(), "target", temp.path()).unwrap();
        assert_eq!(publish_noreplace(&prepared, &target).unwrap_err().0, "outcome_unknown");
        assert_eq!(std::fs::read(&target).unwrap(), b"original");
        assert_eq!(std::fs::read(&prepared).unwrap(), b"new");
        assert!(crate::session_writer_fence::assert_session_writable(&agent, "source").is_err());
        assert!(crate::session_writer_fence::assert_session_writable(&agent, "target").is_err());
    }

    #[test]
    fn malformed_or_partial_staged_output_is_not_publishable() {
        assert!(validate_staged_entries(b"{\"type\":\"session\"}\n{broken}\n").is_err());
        assert!(validate_staged_entries(b"{\"type\":\"session\"}\n{\"type\":\"message\",\"id\":\"a\",\"parentId\":null}").is_err());
        assert!(validate_staged_entries(b"{\"type\":\"session\"}\n{\"type\":\"message\",\"id\":\"a\",\"parentId\":\"missing\"}\n").is_err());
    }
}
